def publish(pd):
    d = json.dumps(pd).encode()
    req = urllib.request.Request(API, data=d, headers={"Authorization": f"Basic {AUTH}", "Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req) as resp:
            r = json.loads(resp.read().decode()); return r.get("id"), r.get("link", "")
    except urllib.error.HTTPError as e: print(f"  HTTP {e.code}: {e.read().decode()[:200]}"); return None, None
    except Exception as e: print(f"  Error: {e}"); return None, None

def main():
    upload_all_images()
    total = len(POSTS)
    print(f"{'='*60}\n총 {total}개 발행 시작\n{'='*60}")
    published_urls = []
    for i, post in enumerate(POSTS, 1):
        content = build(post)
        payload = {"title": post["title"], "content": content, "status": "publish", "slug": post["slug"], "categories": [post["cat"]]}
        fid = get_fid(post["slug"])
        if fid: payload["featured_media"] = fid
        pid, link = publish(payload)
        if pid:
            print(f"[{i}/{total}] OK | ID:{pid} | {post['title']}")
            if link: print(f"  -> {link}"); published_urls.append(link)
        else: print(f"[{i}/{total}] FAIL | {post['title']}")
        time.sleep(1)
    print(f"\n발행 완료! ({len(published_urls)}개)\n")

    # 인덱싱
    if published_urls:
        print(f"{'='*60}\nIndexNow ({len(published_urls)}개)\n{'='*60}")
        payload = {"host":"devupbox.com","key":"8dbbd7d6729b4a65b7dce4b9083c65e3","keyLocation":"https://devupbox.com/8dbbd7d6729b4a65b7dce4b9083c65e3.txt","urlList":published_urls}
        data = json.dumps(payload).encode()
        for n, ep in [("Naver","https://searchadvisor.naver.com/indexnow"),("Bing","https://www.bing.com/indexnow"),("Yandex","https://yandex.com/indexnow")]:
            req = urllib.request.Request(ep, data=data, method="POST"); req.add_header("Content-Type","application/json; charset=utf-8")
            try:
                with urllib.request.urlopen(req, timeout=30) as r: print(f"  {n}: HTTP {r.status}")
            except urllib.error.HTTPError as e: print(f"  {n}: HTTP {e.code}")
            except Exception as e: print(f"  {n}: {e}")

        print(f"\n{'='*60}\nGoogle Indexing API\n{'='*60}")
        try:
            from google.oauth2 import service_account
            from googleapiclient.discovery import build as gb
            creds = service_account.Credentials.from_service_account_file("devupbox.json", scopes=["https://www.googleapis.com/auth/indexing"])
            svc = gb("indexing","v3",credentials=creds); ok=0
            for idx,u in enumerate(published_urls,1):
                try: svc.urlNotifications().publish(body={"url":u,"type":"URL_UPDATED"}).execute(); print(f"  [{idx}/{len(published_urls)}] OK"); ok+=1
                except Exception as e: print(f"  [{idx}/{len(published_urls)}] FAIL | {str(e)[:50]}")
                time.sleep(3)
            print(f"\n  Google: {ok}/{len(published_urls)}")
        except Exception as e: print(f"  Google 실패: {e}")
    print("\n모든 작업 완료!")

if __name__ == "__main__":
    main()
